mapper.select:
SELECT ID,EVENT_TYPE,MODULE,ACTION,USER_ID,USERNAME,RESOURCE_TYPE,RESOURCE_ID,TASK_ID,RESULT_STATUS,
       BUSINESS_RESULT,ACTION_DESC,DETAIL,REQUEST_ID,TRACE_ID,SOURCE_IP,OCCURRED_AT,CREATED_AT,
       RESOURCE_NAME,BEFORE_DATA,AFTER_DATA,FAILURE_REASON,
       CONFIRMATION_FIELD_CODE,CONFIRMATION_FIELD_NAME,CONFIRMATION_FIELD_VALUE,
       CONFIRMATION_RULE_PROMPT,CONFIRMATION_AI_PROMPT,CONFIRMATION_NOTE
FROM AUDIT_OPERATION_LOG

  USER_ID=#{userId}
  AND ACTION=#{action}
  AND RESOURCE_TYPE=#{resourceType}
  AND OCCURRED_AT >= #{from}AND OCCURRED_AT <= #{to}
 ORDER BY OCCURRED_AT DESC, ID DESC
